def f213(R,V):
    # (2,1|3): u = (1,u1,u2,-1-u1-u2, 0) in row 1; U_0 = u^perp cap H_4 spanned by cross4(1,u,e_k), k = 0..3 (4 spanning vectors);
    # column 4 = all of 1^perp (rows).  Spanning sets are fine: the FO equations only need M = span.
    c=R.const; u=[c(1),V('u1'),V('u2'),scal(add(add(c(1),V('u1')),V('u2')),-1)]
    one=[c(1)]*4; Bs=[]
    for k in range(4):
        ek=[c(1) if j==k else {} for j in range(4)]; g=cross4(R,one,u,ek); Z=Zm(); rowv(Z,0,g+[{}]); Bs.append(Z)
    Z=Zm(); rowv(Z,1,u+[{}]); Bs.append(Z)
    for i in (1,2,3):
        Z=Zm(); Z[0][4]=c(1); Z[i][4]=c(-1); Bs.append(Z)
    return Bs
