def det4(M):
    tot={}
    for pp in itertools.permutations(range(4)):
        sg=1
        for i in range(4):
            for j in range(i+1,4):
                if pp[i]>pp[j]: sg=-sg
        t={tuple([0]*len(M[0][0] and list(M[0][0].keys())[0] or ())):1} if False else None
        prod=None
        for i in range(4):
            e=M[i][pp[i]]
            if not e: prod={}; break
            prod=e if prod is None else mul(prod,e)
        if prod: tot=add(tot,prod,sg)
    return tot
