# ---- round 14: deformations of 3-dim single-line parts (NOTES-reg2 22.2): v_b -> v_b + e_tgt (B v_b), B = adj(G) S, S = skew(svec)
def _defo3(fname,kind,idx,tgt,svec,extra):
    p_,f_,d_,r_=FAMS[fname]
    def fb(R,V,f_=f_):
        Bs=f_(R,V); c=R.const
        def supp(B):
            cells=[(i,j) for i in range(4) for j in range(5) if B[i][j]]; return set(i for i,j in cells), set(j for i,j in cells)
        g=[k for k,B in enumerate(Bs) if (supp(B)[1]=={idx} if kind=='col' else supp(B)[0]=={idx})][:3]
        v=[[Bs[k][i][idx] for i in range(4)] if kind=='col' else [Bs[k][idx][j] for j in range(5)] for k in g]
        def dt(a,b):
            t={}
            for x,y in zip(a,b):
                if x and y: t=add(t,mul(x,y))
            return t
        G=[[dt(v[a],v[b]) for b in range(3)] for a in range(3)]
        def d2(a,b,cc,dd): return add(mul(a,dd) if a and dd else {},mul(b,cc) if b and cc else {},-1)
        adj=[[None]*3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                rr=[x for x in range(3) if x!=b]; cl=[x for x in range(3) if x!=a]
                m=d2(G[rr[0]][cl[0]],G[rr[0]][cl[1]],G[rr[1]][cl[0]],G[rr[1]][cl[1]]); adj[a][b]=m if (a+b)%2==0 else scal(m,-1)
        t=V('t') if all(not isinstance(x,str) for x in svec) else None
        s1,s2,s3=[V(x) if isinstance(x,str) else scal(t,x) for x in svec]
        Sm=[[{},s3,scal(s2,-1)],[scal(s3,-1),{},s1],[s2,scal(s1,-1),{}]]
        for b in range(3):
            Bcol=[{} for _ in range(3)]
            for a in range(3):
                for cc in range(3):
                    if adj[a][cc] and Sm[cc][b]: Bcol[a]=add(Bcol[a],mul(adj[a][cc],Sm[cc][b]))
            img=[{} for _ in range(len(v[0]))]
            for a in range(3):
                if Bcol[a]:
                    for k in range(len(v[0])):
                        if v[a][k]: img[k]=add(img[k],mul(Bcol[a],v[a][k]))
            kk=g[b]
            for k in range(len(v[0])):
                if img[k]:
                    if kind=='col': Bs[kk][k][tgt]=add(Bs[kk][k][tgt],img[k]) if Bs[kk][k][tgt] else img[k]
                    else: Bs[kk][tgt][k]=add(Bs[kk][tgt][k],img[k]) if Bs[kk][tgt][k] else img[k]
        return Bs
    newp=[x for x in svec if isinstance(x,str)] or ['t']
    return (p_+newp,fb,d_,r_+extra)
