def _fixbase(fname,fix):          # substitute fixed rational values for base parameters (round 14)
    p_,f_,d_,r_=FAMS[fname]
    def fb(R,V,f_=f_):
        from fractions import Fraction as _Fr; import math as _m
        Bs=f_(R,lambda n: (R.const(fix[n]) if fix[n]!=0 else {}) if n in fix else V(n))
        for B in Bs:                      # clear denominators per element (scaling an element does not change the space)
            L_=1
            for row in B:
                for e in row:
                    if e:
                        for v in e.values(): L_=L_*_Fr(v).denominator//_m.gcd(L_,_Fr(v).denominator)
            for i in range(len(B)):
                for j in range(len(B[i])):
                    if B[i][j]: B[i][j]={k:int(_Fr(v)*L_) for k,v in B[i][j].items()}
        return Bs
    return ([x for x in p_ if x not in fix],fb,d_,r_)
